import { Fragment } from "react";
import "./App.css";
import Stopwatch from "./Stopwatch";
import React from "react";

function App() {
  const genders = { m: "Homme", f: "Femme", nb: "Non-Binaire" };
  return (
    <div className="App">
      {Object.keys(genders).map((gender) => (
        <Fragment>
          <Stopwatch
            genderId={gender}
            display={genders[gender]}
            key={gender}
            running={true}
            time={0}
          />
          <button>Start {genders[gender]}</button>
        </Fragment>
      ))}
    </div>
  );
}

export default App;
